import{_ as i,l as o,o as e,c as n,v as t,p as s,x as l,d,i as E,S as A}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"量化后退化模式","description":"","frontmatter":{"title":"量化后退化模式","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/quant-eval-degradation.md","filePath":"llm/quant-eval-degradation.md","lastUpdated":1789023840000}'),p={name:"llm/quant-eval-degradation.md"};function h(B,a,m,_,c,u){const r=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="量化后退化模式" tabindex="-1">量化后退化模式 <a class="header-anchor" href="#量化后退化模式" aria-label="Permalink to &quot;量化后退化模式&quot;">​</a></h1><div class="epigraph"><p>平均分还在，算术先乱、格式先崩、长上下文先饱和。退化是有结构的，不是「整体糊了一层」。下一刀该加 bit 还是该换校准，取决于哪一种模式。</p><footer>—— 对照离群通道、lm_head 精度与长序列激活；指标见上一课</footer></div><p><a href="/llm/quant-error-metrics">误差度量</a> 要求分能力报数。本课写 <strong>常见死法</strong>，把数映射到处方。缺口是诊断，不是又一个量化器。<a href="/llm/why-activation-outliers">离群</a> 与 <a href="/llm/gptq">GPTQ</a> 的校准过拟合在此会合。量化基础课序到此结束；下一单元稀疏会引入另一种退化（支撑被删）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>模式 A：短 PPL 几乎不动，多位数加法、单位换算失败——精细幅度被粗格子吃掉，lm_head 或末层该留精度。模式 B：拒绝指令格式、乱说话、重复——可能是特殊 token 通道被量化，或校准没有 chat template。模式 C：短上下文正常，长请求爆或变傻——RoPE / 激活离群在长度上才出现，校准太短。模式 D：某一语种或代码崩——校准域偏。模式 E：NaN / inf——FP8 溢出或尺度为零。</p><p>把这些都叫「量化掉点」会开错药：A 要混精，C 要加长校准，E 要缩放，而不是一律回到 FP16。</p><p><span class="marginnote">与剪枝退化不同：剪层伤深度依赖与长链推理；量化伤幅度与离群维。联合压缩时先分清是哪一刀切的，见量化与剪枝分工课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>诊断顺序：饱和率与 inf 计数 → 分能力表 → 出问题样本的层激活直方图 → 对照校准是否覆盖该模式。处方表：溢出降 \\(s\\) 或改 FP8 缩放；离群绑架加通道平滑或该维留高精；头层差保护 embed/lm_head；域差换校准；核解包则性能问题不是质量问题。</p>',9)),(e(),s(A,null,{default:l(()=>[E(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SYM%5B%22%E7%97%87%E7%8A%B6%22%5D%20--%3E%20A%5B%22%E7%AE%97%E6%9C%AF%E5%B4%A9%22%5D%0A%20%20SYM%20--%3E%20B%5B%22%E6%A0%BC%E5%BC%8F%E5%B4%A9%22%5D%0A%20%20SYM%20--%3E%20C%5B%22%E9%95%BF%E4%B8%8A%E4%B8%8B%E6%96%87%E5%B4%A9%22%5D%0A%20%20SYM%20--%3E%20D%5B%22%E5%9F%9F%E5%B4%A9%22%5D%0A%20%20A%20--%3E%20MIX%5B%22%E6%B7%B7%E7%B2%BE%E5%A4%B4%20%2F%20%E6%9C%AB%E5%B1%82%22%5D%0A%20%20B%20--%3E%20CAL%5B%22%E6%A0%A1%E5%87%86%E5%90%AB%E6%A8%A1%E6%9D%BF%22%5D%0A%20%20C%20--%3E%20LEN%5B%22%E5%8A%A0%E9%95%BF%E6%A0%A1%E5%87%86%20%2F%20%E5%B9%B3%E6%BB%91%22%5D%0A%20%20D%20--%3E%20DOM%5B%22%E6%8D%A2%E6%A0%A1%E5%87%86%E5%9F%9F%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>回归集应永久包含：短 PPL、一个算术包、一个格式包、一条长上下文、一个域外包。量化发布跟模型发布一样走这套，而不是只看平均。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>argmax 对 logits 的小扰动不敏感，所以选择题虚稳（度量课）。算术需要的 logit 间隔更细，同一扰动先死。格式依赖少数特殊维，离群课说过它们可能是功能钉，量化或剪都伤。长度把激活动态范围拉开，格子在短校准上估的 \\(s\\) 不够。机制不同，所以不能用一个全局 \\(\\Delta\\)PPL 当充分统计量。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要用「再训一下 QAT」掩盖未诊断的模式——QAT 贵，且可能修 A 不修 C。不要把投机解码的拒绝率上升全算在量化上（草稿模型也可能被量化）。稀疏单元从 SparseGPT 开始，误差来自硬零，退化模式会换一套，但验收纪律相同：分能力、禁连乘加速比。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>退化有结构：算术、格式、长度、域、溢出，处方不同。</li><li>选择题虚稳；用分能力回归集发布。</li><li>先诊断饱和 / 离群 / 校准覆盖，再决定混精还是换数据。</li><li>与剪枝伤深度依赖区分，联合时对症状归因。</li><li>出处：离群与 GPTQ/AWQ 校准实践；度量课的指标层级。</li></ul>',7))])}const D=i(p,[["render",h]]);export{f as __pageData,D as default};
